-- Almasu: FTC parts catalog for the bot (266 parts). Run after schema.sql. Safe to re-run.
-- Branded parts carry names, part numbers and photos checked against the makers' sites
-- (site/data/parts-catalog.json); generic items have no brand or part number.
-- Regenerated from the live database after supabase/fix_ftc_catalog.sql.

on conflict (name, coalesce(brand, '')) do update set
  sku = excluded.sku, category = excluded.category, image = excluded.image, program = excluded.program;
